    board:state.roleNavigation.includes('leads')&&(state.assignedNavigation===null||state.assignedNavigation.includes('leads'))?pipeline('/board?page=1&limit=1'):Promise.resolve(null),followups:state.roleNavigation.includes('leads')&&(state.assignedNavigation===null||state.assignedNavigation.includes('leads'))?pipeline('/follow-ups?period=all&page=1&limit=8'):Promise.resolve(null),
