ntent=tr('Currency','العملة');el('referenceLabel').textContent=tr('Sale reference (optional)','مرجع البيع (اختياري)');el('noteLabel').textContent=tr('Note (optional)','ملاحظة (اختيارية)');el('submitSale').textContent=tr('Submit for approval','إرسال للاعتماد');el('refresh').textContent=tr('Refresh','تحديث');
el('saleForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=el('submitSale'),currency=form.elements.currency.value.trim().toUpperCase();let amountMinor;try{if(!/^[A-Z]{3}$/.test(currency))throw Error();amountMinor=toMinor(form.elements.amount.value,currency);}catch{message('error',tr('Enter a valid amount using the currency’s decimal places.','أدخل مبلغًا صحيحًا وفق المنازل العشرية للعملة.'));return;}button.disabled=true;try{await api('/deals',{method:'POST',body:JSON.stringify({leadId:form.elements.leadId.value,productId:form.elements.productId.value,amountMinor,currency,saleReference:form.elements.saleReference.value||undefined,sellerNote:form.elements.sellerNote.value||undefined,idempotencyKey:crypto.randomUUID()})});form.elements.saleReference.value='';form.elements.sellerNote.value='';form.elements.amount.value='';message('success',tr('Sale submitted for approval.','تم إرسال عملية البيع للاعتماد.'));await load();}catch(error){message('error',mapError(error.code));}finally{button.disabled=false;}});
el('targetPeriod').value=qatarPeriod();el('reportPeriod').value=el('targetPeriod').value;el('targetsTitle').textContent=tr('Targets & performance','الأهداف والأداء');el('periodLabel').textContent=tr('Month','الشهر');el('reportPeriodLabel').textContent=tr('Report month','شهر التقرير');el('targetPeriod').addEventListener('change',()=>state.section==='targets'&&load());el('reportPeriod').addEventListener('change',()=>{if(state.section==='reports')load();});el('exportSalesReport').textContent=tr('Download CSV','تنزيل CSV');el('exportSalesReport').addEventListener('click',()=>{try{downloadSalesReport();}catch{message('error',tr('The report could not be exported. Refresh and try again.','تعذر تصدير التقرير. حدّث الصفحة وحاول مرة أخرى.'));}});el('dealFilter').addEventListener('change',load);el('commissionFilter').addEventListener('change',load);el('refresh').addEventListener('click',load);document.documentElement.lang=ar()?'ar':'en';document.documentElement.dir=ar()?'rtl':'ltr';renderView();load();
